  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

function isToken(word) {
  return TOKEN_RE.test(word)
}

function integerAtLeast(word, field, least, lineNo) {
  if (!INT_RE.test(word)) throw new ParseError(lineNo, `${field} must be an integer of at least ${least}`)
  const value = BigInt(word)
  if (value < least) throw new ParseError(lineNo, `${field} must be an integer of at least ${least}`)
  return value
