class Bucket {
  constructor(name, capacity, refill, per) {
    this.name = name
    this.capacity = capacity
    this.refill = refill
    this.per = per
    // tokens are stored as a numerator over `per`, so fractions stay exact
    this.cap = capacity * per
    this.states = new Map()
  }

  advance(key, tick) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { num: this.cap, last: tick }
      this.states.set(key, state)
      return
    }
    const elapsed = tick - state.last
    if (elapsed > 0n) {
      state.num += this.refill * elapsed
      if (state.num > this.cap) state.num = this.cap
      state.last = tick
    }
  }

  allows(key) {
    return this.states.get(key).num >= this.per
  }

  record(key) {
    const state = this.states.get(key)
    state.num -= this.per
  }
}

class Window {
  constructor(name, limit, span) {
    this.name = name
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  advance(key, tick) {
    let ticks = this.states.get(key)
    if (ticks === undefined) {
      ticks = []
      this.states.set(key, ticks)
    }
    const cutoff = tick - this.span
    let drop = 0
    while (drop < ticks.length && ticks[drop] <= cutoff) drop += 1
    if (drop > 0) ticks.splice(0, drop)
  }

  allows(key) {
    return BigInt(this.states.get(key).length) < this.limit
  }

  record(key) {
    this.states.get(key).push(this.currentTick)
  }
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map()
  const routes = new Map()
  const events = []
  let seenEvent = false
  let lastTick = null

