    return this.states.get(key).num >= this.per
  }

  record(key) {
    const state = this.states.get(key)
    state.num -= this.per
  }
}

class Window {
  constructor(name, limit, span) {
    this.name = name
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  advance(key, tick) {
    let ticks = this.states.get(key)
    if (ticks === undefined) {
      ticks = []
      this.states.set(key, ticks)
    }
    const cutoff = tick - this.span
    let drop = 0
    while (drop < ticks.length && ticks[drop] <= cutoff) drop += 1
    if (drop > 0) ticks.splice(0, drop)
  }

  allows(key) {
    return BigInt(this.states.get(key).length) < this.limit
  }

  record(key) {
    this.states.get(key).push(this.currentTick)
  }
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map()
  const routes = new Map()
  const events = []
  let seenEvent = false
  let lastTick = null

  for (let i = 0; i < lines.length; i += 1) {
    const lineNo = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/)
    const directive = words[0]

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (seenEvent) throw new ParseError(lineNo, 'declarations must come before the first event')
    }

    if (directive === 'bucket') {
      if (words.length !== 5) throw new ParseError(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      const name = words[1]
      if (!isToken(name)) throw new ParseError(lineNo, `invalid policy name ${name}`)
      const capacity = integerAtLeast(words[2], 'capacity', 1n, lineNo)
      const refill = integerAtLeast(words[3], 'refill', 0n, lineNo)
      const per = integerAtLeast(words[4], 'per', 1n, lineNo)
      if (policies.has(name)) throw new ParseError(lineNo, `policy ${name} is declared twice`)
      policies.set(name, new Bucket(name, capacity, refill, per))
    } else if (directive === 'window') {
      if (words.length !== 4) throw new ParseError(lineNo, 'expected window <name> <limit> <span>')
      const name = words[1]
      if (!isToken(name)) throw new ParseError(lineNo, `invalid policy name ${name}`)
      const limit = integerAtLeast(words[2], 'limit', 0n, lineNo)
      const span = integerAtLeast(words[3], 'span', 1n, lineNo)
      if (policies.has(name)) throw new ParseError(lineNo, `policy ${name} is declared twice`)
      policies.set(name, new Window(name, limit, span))
    } else if (directive === 'route') {
      if (words.length < 3) throw new ParseError(lineNo, 'expected route <prefix> <policy>...')
      const prefix = words[1]
      if (!isToken(prefix)) throw new ParseError(lineNo, `invalid route prefix ${prefix}`)
      const named = []
      for (const name of words.slice(2)) {
        if (!isToken(name)) throw new ParseError(lineNo, `invalid policy name ${name}`)
        const policy = policies.get(name)
        if (policy === undefined) throw new ParseError(lineNo, `unknown policy ${name}`)
        named.push(policy)
      }
      if (routes.has(prefix)) throw new ParseError(lineNo, `prefix ${prefix} is routed twice`)
      routes.set(prefix, named)
    } else if (directive === 'event') {
      if (words.length !== 3) throw new ParseError(lineNo, 'expected event <tick> <key>')
      const tick = integerAtLeast(words[1], 'tick', 0n, lineNo)
      const key = words[2]
      if (!isToken(key)) throw new ParseError(lineNo, `invalid key ${key}`)
      if (lastTick !== null && tick < lastTick) {
        throw new ParseError(lineNo, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      seenEvent = true
      events.push({ tick, key })
    } else {
      throw new ParseError(lineNo, `unknown directive ${directive}`)
    }
  }

  return { routes, events }
}

function routeFor(routes, key) {
  let best = null
  let bestLength = -1
  for (const [prefix, policies] of routes) {
    if (key.startsWith(prefix) && prefix.length > bestLength) {
      best = policies
      bestLength = prefix.length
    }
  }
  return best === null ? [] : best
}

export function simulate({ routes, events }) {
  const cache = new Map()
  const verdicts = []
  for (const { tick, key } of events) {
    let policies = cache.get(key)
    if (policies === undefined) {
      policies = routeFor(routes, key)
      cache.set(key, policies)
    }
    for (const policy of policies) {
      policy.advance(key, tick)
      policy.currentTick = tick
    }
    let denier = null
    for (const policy of policies) {
      if (!policy.allows(key)) {
        denier = policy.name
        break
      }
    }
    if (denier === null) {
      for (const policy of policies) policy.record(key)
    }
    verdicts.push({ tick, key, denier })
  }
  return verdicts
}

export function replayLines(verdicts) {
  return verdicts.map((v) => (v.denier === null ? `${v.tick} ${v.key} allow` : `${v.tick} ${v.key} deny ${v.denier}`))
}

export function summaryLines(verdicts) {
  const perKey = new Map()
  let allowed = 0
  let denied = 0
  for (const v of verdicts) {
    let counts = perKey.get(v.key)
    if (counts === undefined) {
      counts = { allowed: 0, denied: 0 }
      perKey.set(v.key, counts)
    }
    if (v.denier === null) {
      counts.allowed += 1
      allowed += 1
    } else {
      counts.denied += 1
      denied += 1
    }
  }
  const keys = [...perKey.keys()].sort()
  const lines = keys.map((key) => {
    const counts = perKey.get(key)
    return `${key} allowed=${counts.allowed} denied=${counts.denied}`
  })
  lines.push(`total allowed=${allowed} denied=${denied}`)
  return lines
}
