/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync } from 'node:fs'
import { ParseError, parse, replayLines, simulate, summaryLines } from './limiter.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const argv = process.argv.slice(2)
  const mode = argv.length === 1 ? argv[0] : null
  if (mode !== 'replay' && mode !== 'summary') fail('usage: cli.js replay|summary')

  let text = ''
  try {
    text = readFileSync(0, 'utf8')
  } catch {
    text = ''
  }

  let verdicts
  try {
    verdicts = simulate(parse(text))
  } catch (error) {
    if (error instanceof ParseError) fail(error.message)
    throw error
  }

  const lines = mode === 'replay' ? replayLines(verdicts) : summaryLines(verdicts)
  process.stdout.write(lines.map((line) => `${line}\n`).join(''))
}

main()
"}

